MultiLanguageItemData['en'][5696] = {name = "Tablet of Shock", additional_info = "Classes: Shaman\nRequires Level 4\n[q2]Use: Teaches Shock (Rank 1).\n\n[q2]Instantly throws a bolt of lightning at the target for 25 to 28 damage.\nSell Price:"}
MultiLanguageItemData['en'][5697] = {name = "Tablet of Healing Totem", additional_info = "Classes: Shaman\nRequires Level 6\n[q2]Use: Teaches Healing Totem (Rank 1).\n\n[q2]Summons a Healing Stream Totem with 5 health at the feet of the caster for 2 min that heals group members within 20 yards for 6 every 2 seconds.\nSell Price:"}
MultiLanguageItemData['en'][5698] = {name = "Tablet of Lightning Shield", additional_info = "Classes: Shaman\nRequires Level 8\n[q2]Use: Teaches Lightning Shield (Rank 1).\n\n[q2]The caster is surrounded by 3 balls of lightning. When a spell, melee or ranged attack hits the caster, the attacker will be struck for 13 Nature damage. This expends one lightning ball. Only one ball will fire every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time. (3.5s cooldown)\nSell Price:"}
MultiLanguageItemData['en'][5699] = {name = "Tablet of Ghost Wolf", additional_info = "Classes: Shaman\nRequires Level 12\n[q2]Use: Teaches Ghost Wolf (Rank 1).\n\n[q2]Turns the Shaman into a Ghost Wolf, increasing speed by 40%. Only useable outdoors.\nSell Price:"}
MultiLanguageItemData['en'][5700] = {name = "Tablet of Healing Totem II", additional_info = "Classes: Shaman\nRequires Level 12\n[q2]Use: Teaches Healing Totem (Rank 2).\n\n[q2]Summons a Healing Stream Totem with 5 health at the feet of the caster for 2 min that heals group members within 20 yards for 8 every 2 seconds.\nSell Price:"}
MultiLanguageItemData['en'][5701] = {name = "Tablet of Sentry Totem", additional_info = "Classes: Shaman\nRequires Level 14\n[q2]Use: Teaches Sentry Totem.\n\n[q2]Summons an immobile Sentry Totem with 100 health at your feet for 5 min that allows vision of nearby area and warns of enemies that attack it. Right-Click on buff to switch back and forth between totem sight and shaman sight.\nSell Price:"}
MultiLanguageItemData['en'][5702] = {name = "Tablet of Agitating Totem II", additional_info = "Classes: Shaman\nRequires Level 18\n[q2]Use: Teaches Agitating Totem (Rank 2).\n\n[q2]Summons a Stoneclaw Totem with 150 health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it. Enemies attacking the Stoneclaw Totem have a 50% chance to be stunned for 3 sec.\nSell Price:"}
MultiLanguageItemData['en'][5703] = {name = "Tablet of Thunderclap", additional_info = "Classes: Shaman\nRequires Level 20\n[q2]Use: Teaches Thunder Clap (Rank 1).\n\n[q2]Blasts nearby enemies increasing the time between their attacks by 10% for 10 sec and doing 10 damage to them. This ability causes additonal threat and will affect up to 4 targets.\nSell Price:"}
MultiLanguageItemData['en'][5704] = {name = "Tablet of Water Breathing", additional_info = "Classes: Shaman\nRequires Level 20\n[q2]Use: Teaches Water Breathing.\n\n[q2]Allows the target to breathe underwater for 10 min.\nSell Price:"}
