MultiLanguageItemData['en'][5719] = {name = "Grimoire of Life Drain II", additional_info = "Classes: Warlock\nRequires Level 22\n[q2]Use: Teaches Drain Life (Rank 2).\n\n[q2]Transfers 17 health every 1 sec from the target to the caster. Lasts 5 sec.\nSell Price:"}
MultiLanguageItemData['en'][5720] = {name = "Grimoire of Curse of Mannoroth II", additional_info = "Classes: Warlock\nRequires Level 20\n[q2]Use: Teaches Curse of Weakness (Rank 2).\n\n[q2]Target's melee attack power is reduced by 41 for 2 min. Only one Curse per Warlock can be active on any one target.\nSell Price:"}
MultiLanguageItemData['en'][5721] = {name = "Grimoire of Create Spellstone", additional_info = "Classes: Warlock\nRequires Level 34\n[q2]Use: Teaches Create Spellstone.\n\n[q2]Creates a Spellstone for the caster. When equipped and used, the Spellstone dispels all harmful magic effects from the caster. In addition, equipping the Spellstone improves your spell critical strike rating by 8.\n\n Conjured items disappear if logged out for more than 15 minutes.\nSell Price:\nSpellstone\nConjured Item\nBinds when picked up\nUnique\nRelic\nRequires Level 36\n[q2]Use: Dispels all harmful magic effects from the caster. (3 Min Cooldown)\n\n[q2]Equip: Increases your spell critical strike rating by 8.\nRequires Soul Shard"}
MultiLanguageItemData['en'][5722] = {name = "Grimoire of Siphon Mana II", additional_info = "Classes: Warlock\nRequires Level 36\n[q2]Use: Teaches Drain Mana (Rank 2).\n\n[q2]Transfers 68 Mana every 1 sec from the target to the caster. Lasts 5 sec.\nSell Price:"}
MultiLanguageItemData['en'][5723] = {name = "Grimoire of Curse of Sargeras III", additional_info = "Classes: Warlock\nRequires Level 36\n[q2]Use: Teaches Curse of Agony (Rank 3).\n\n[q2]Curses the target with agony, causing 324 Shadow damage over 24 sec. This damage is dealt slowly at first, and builds up as the Curse reaches its full duration. Only one Curse per Warlock can be active on any one target.\nSell Price:"}
MultiLanguageItemData['en'][5724] = {name = "Grimoire of Curse of Tongues", additional_info = "Classes: Warlock\nRequires Level 22\n[q2]Use: Teaches Curse of Tongues (Rank 1).\n\n[q2]Forces the target to speak in Demonic, increasing the casting time of all spells by 50%. Only one Curse per Warlock can be active on any one target. Lasts 30 sec.\nSell Price:"}
