MultiLanguageItemData['en'][20975] = {name = "Design: The Jade Eye", additional_info = "Requires Jewelcrafting (170)\n[q2]Use: Teaches you how to craft The Jade Eye.\nSell Price: \n[q2]The Jade Eye\nBinds when equipped\nUnique-Equipped\nFinger\n+5 Stamina\nRequires Level 32\n[q2]Equip: Increases defense rating by 6.\nSell Price: \nRequires Jade , Elemental Earth (2)"}
MultiLanguageItemData['en'][20976] = {name = "[q2]Design: Citrine Pendant of Golden Healing", additional_info = "Binds when picked up\nRequires Jewelcrafting (190)\n[q2]Use: Teaches you how to craft a Citrine Pendant of Golden Healing.\n\n\n[q2]Citrine Pendant of Golden Healing\nBinds when equipped\nNeck\n+3 Intellect\nRequires Level 34\n[q2]Equip: Increases healing done by up to 20 and damage done by up to 7 for all magical spells and effects.\n\n[q2]Use: Restores 3 health to all nearby party members every 5 seconds for 30 min.\n10 Charges\nSell Price: \nRequires Citrine , Elemental Water (2), Gold Bar (2), Bronze Setting"}
