MultiLanguageItemData['en'][21948] = {name = "Design: Opal Necklace of Impact", additional_info = "Requires Jewelcrafting (250)\n[q2]Use: Teaches you how to craft an Opal Necklace of Impact.\nSell Price: \n[q3]Opal Necklace of Impact\nBinds when equipped\nUnique\nNeck\nRequires Level 45\n[q2]Equip: +3 Weapon Damage.\nSell Price:\nRequires Large Opal (2), Thorium Setting (2), Truesilver Bar (4), Large Radiant Shard (2), Mithril Filigree (2)"}
MultiLanguageItemData['en'][21949] = {name = "[q2]Design: Ruby Serpent", additional_info = "Requires Jewelcrafting (260)\n[q2]Use: Teaches you how to craft a Ruby Serpent.\nSell Price:\n[q2]Figurine - Ruby Serpent\nBinds when picked up\nUnique\nTrinket\n+4 Stamina\n+4 Intellect\nRequires Level 47\nRequires Jewelcrafting (260)\n[q2]Use: Increases damage and healing done by magical spells and effects by up to 100 for 20 sec. (5 Min Cooldown)\nSell Price:\nRequires Star Ruby (2), Essence of Fire (2), Flask of Big Mojo (4), Truesilver Bar (2)"}
