MultiLanguageItemData['en'][21952] = {name = "Design: Emerald Crown of Destruction", additional_info = "Requires Jewelcrafting (275)\n[q2]Use: Teaches you how to craft an Emerald Crown of Destruction.\nSell Price:\n[q3]Emerald Crown of Destruction\nBinds when equipped\n{Head} {Cloth}\n64 Armor\nDurability 50 / 50\nRequires Level 50\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 30.\n\n[q2]Equip: Increases your spell critical strike rating by 14.\nSell Price: \nRequires Huge Emerald (2), Large Opal (2), Blue Sapphire (2), Arcanite Bar (2), Thorium Bar (2)"}
MultiLanguageItemData['en'][21953] = {name = "[q2]Design: Emerald Owl", additional_info = "Requires Jewelcrafting (285)\n[q2]Use: Teaches you how to craft an Emerald Owl.\nSell Price: \n[q2]Figurine - Emerald Owl\nBinds when picked up\nUnique\nTrinket\nRequires Level 50\nRequires Jewelcrafting (285)\n[q2]Equip: Restores 2 mana per 5 sec.\n\n[q2]Use: Restores 60 mana every second for 12 sec. (5 Min Cooldown)\nSell Price: \nRequires Huge Emerald (2), Arcanite Bar (2), Thorium Bar (2), Powerful Mojo (4)"}
MultiLanguageItemData['en'][21954] = {name = "Design: Ring of Bitter Shadows", additional_info = "Requires Jewelcrafting (285)\n[q2]Use: Teaches you how to craft a Ring of Bitter Shadows.\nSell Price:\n[q2]Ring of Bitter Shadows\nBinds when equipped\nUnique-Equipped\nFinger\nRequires Level 52\n[q2]Equip: Increases damage done by Shadow spells and effects by up to 20.\nSell Price: \nRequires Arcane Crystal , Essence of Undeath (2), Demonic Rune"}
MultiLanguageItemData['en'][21955] = {name = "[q2]Design: Black Diamond Crab", additional_info = "Binds when picked up\nRequires Jewelcrafting (300)\n[q2]Use: Teaches you how to craft a Black Diamond Crab.\n\n\n[q3]Figurine - Black Diamond Crab\nBinds when picked up\nUnique\nTrinket\nRequires Level 55\nRequires Jewelcrafting (300)\n[q2]Equip: Increases defense rating by 9.\n\n[q2]Use: Reduces melee damage taken by 35 for 20 sec. (5 Min Cooldown)\nSell Price: \nRequires Pristine Black Diamond (4), Black Diamond (4), Azerothian Diamond (2), Arcanite Bar (2), Thorium Bar (4)"}
MultiLanguageItemData['en'][21956] = {name = "[q2]Design: Dark Iron Scorpid", additional_info = "Binds when picked up\nRequires Jewelcrafting (300)\n[q2]Use: Teaches you how to craft a Dark Iron Scorpid.\n\n\n[q3]Figurine - Dark Iron Scorpid\nBinds when picked up\nUnique\nTrinket\n+9 Agility\nRequires Level 55\nRequires Jewelcrafting (300)\n[q2]Use: Every swing poisons your foe for 15 damage every second for 20 sec. (5 Min Cooldown)\nSell Price: \nRequires Dark Iron Bar (4), Arcanite Bar (2), Star Ruby (2)"}
MultiLanguageItemData['en'][21957] = {name = "Design: Necklace of the Diamond Tower", additional_info = "Requires Jewelcrafting (305)\n[q2]Use: Teaches you how to craft a Necklace of the Diamond Tower.\nSell Price: \n[q3]Necklace of the Diamond Tower\nBinds when equipped\nNeck\n+3 Arcane Resistance\n+3 Fire Resistance\n+3 Nature Resistance\n+3 Frost Resistance\n+3 Shadow Resistance\nRequires Level 56\n[q2]Equip: Increases defense rating by 17.\nSell Price: \nRequires Azerothian Diamond (2), Thorium Setting (2), Arcanite Bar (2)"}
