MultiLanguageItemData['en'][23802] = {name = "[q3]Schematic: Ornate Khorium Rifle", additional_info = "Requires Engineering (375)\n[q2]Use: Teaches you how to make an Ornate Khorium Rifle.\nSell Price: \n[q3]Ornate Khorium Rifle\nBinds when equipped\n{Ranged} {Gun}\n{144 - 268 Damage} {Speed 3.10}\n(66.45 damage per second)\n+14 Agility\nDurability 75 / 75\nRequires Level 70\n[q2]Equip: Improves hit rating by 13.\nSell Price: \nRequires Hardened Adamantite Tube (2), Khorium Bar (12), Handful of Fel Iron Bolts (4), Noble Topaz (2)"}
MultiLanguageItemData['en'][23803] = {name = "Schematic: Cogspinner Goggles", additional_info = "Requires Engineering (340)\n[q2]Use: Teaches you how to make Cogspinner Goggles.\nSell Price: \n[q3]Cogspinner Goggles\nBinds when equipped\n{Head} {Leather}\n220 Armor\n[q2]<Random enchantment>\nDurability 60 / 60\nRequires Engineering (340)\nSell Price: \nRequires Heavy Knothide Leather (4), Blood Garnet (2), Arcane Dust (8)"}
MultiLanguageItemData['en'][23804] = {name = "[q3]Schematic: Power Amplification Goggles", additional_info = "Requires Engineering (340)\n[q2]Use: Teaches you how to make Power Amplification Goggles.\nSell Price:\n[q3]Power Amplification Goggles\nBinds when equipped\n{Head} {Cloth}\n100 Armor\n+46 Stamina\nDurability 50 / 50\nRequires Engineering (340)\n[q2]Equip: Improves spell critical strike rating by 31.\n\n[q2]Equip: Increases damage and healing done by magical spells and effects by up to 36.\nSell Price: \nRequires Heavy Knothide Leather (4), Flame Spessarite (2), Arcane Dust (8)"}
MultiLanguageItemData['en'][23805] = {name = "Schematic: Ultra-Spectropic Detection Goggles", additional_info = "Requires Engineering (350)\n[q2]Use: Teaches you how to make Ultra-Spectropic Detection Goggles.\nSell Price:\n[q3]Ultra-Spectropic Detection Goggles\nBinds when equipped\n{Head} {Cloth}\n124 Armor\n+48 Stamina\n+47 Spirit\nDurability 50 / 50\nRequires Engineering (350)\n[q2]Equip: Shows the location of all nearby gas clouds on the minimap.\n\n[q2]Use: Allows you to look far into the distance.\nSell Price: \nRequires Heavy Knothide Leather (4), Khorium Bar (2), Deep Peridot (2), Small Prismatic Shard (2)"}
MultiLanguageItemData['en'][23806] = {name = "[q3]Schematic: Hyper-Vision Goggles", additional_info = "Binds when picked up\nRequires Engineering (360)\n[q2]Use: Teaches you how to make Hyper-Vision Goggles.\nSell Price:\n[q3]Hyper-Vision Goggles\nBinds when equipped\n{Head} {Leather}\n232 Armor\nDurability 60 / 60\nRequires Engineering (360)\n[q2]Equip: Improves hit rating by 23.\n\n[q2]Equip: Increases attack power by 84.\n\n[q2]Use: Increases your stealth detection for 15 sec. (2 Min Cooldown)\nSell Price: \nRequires Heavy Knothide Leather (4), Khorium Bar (2), Nightseye (2), Large Prismatic Shard (2)"}
MultiLanguageItemData['en'][23807] = {name = "Schematic: Adamantite Scope", additional_info = "Requires Engineering (335)\n[q2]Use: Teaches you how to make an Adamantite Scope.\nSell Price: \n[q2]Adamantite Scope\nRequires Level 55\n\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its damage by 10.\nSell Price:\nRequires Adamantite Bar (8), Golden Draenite (2)"}
MultiLanguageItemData['en'][23808] = {name = "[q3]Schematic: Khorium Scope", additional_info = "Binds when picked up\nRequires Engineering (360)\n[q2]Use: Teaches you how to make a Khorium Scope.\nSell Price:\n[q3]Khorium Scope\nRequires Level 55\n\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its damage by 12.\nSell Price:\nRequires Hardened Adamantite Tube , Khorium Bar (4), Dawnstone (2)"}
MultiLanguageItemData['en'][23809] = {name = "[q3]Schematic: Stabilized Eternium Scope", additional_info = "Binds when picked up\nRequires Engineering (375)\n[q2]Use: Teaches you how to make a Stabilized Eternium Scope.\nSell Price: \n[q3]Stabilized Eternium Scope\nRequires Level 60\n\n[q2]Use: Attaches a permanent scope to a bow or gun that increases its critical strike rating by 28.\nSell Price:\nRequires Hardened Adamantite Tube (2), Felsteel Stabilizer (6), Star of Elune (2)"}
