MultiLanguageItemData['en'][185924] = {name = "[q3]Pattern: Greater Drums of Restoration", additional_info = "Binds when picked up\nRequires Leatherworking (350)\nRequiresThe Mag'har\n- Honored\n[q2]Use: Teaches you how to craft Greater Drums of Restoration.\nSell Price:\n[q3]Greater Drums of Restoration\nRequires Leatherworking (350)\n\n[q2]Use: Restores 600 health and mana to party members within 40 yards over 15 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n50 Charges\nSell Price:\nRequires Heavy Knothide Leather (6), Nether Dragonscales (4)"}
MultiLanguageItemData['en'][185925] = {name = "[q3]Pattern: Greater Drums of Panic", additional_info = "Binds when picked up\nRequires Leatherworking (370)\nRequiresKeepers of Time\n- Honored\n[q2]Use: Teaches you how to craft Greater Drums of Panic.\nSell Price:\n[q3]Greater Drums of Panic\nRequires Leatherworking (350)\n\n[q2]Use: Unearthly rhythms cause 5 enemies within 8 yds to flee in terror for 2 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n50 Charges\nSell Price:\nRequires Heavy Knothide Leather (6), Fel Hide (4)"}
MultiLanguageItemData['en'][185926] = {name = "[q3]Pattern: Greater Drums of Battle", additional_info = "Binds when picked up\nRequires Leatherworking (365)\nRequiresThe Sha'tar\n- Honored\n[q2]Use: Teaches you how to craft Greater Drums of Battle.\nSell Price:\n[q3]Greater Drums of Battle\nRequires Leatherworking (350)\n\n[q2]Use: Increases melee, ranged and spell haste rating on party members within 40 yards by 80. Lasts 30 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n50 Charges\nSell Price:\nRequires Heavy Knothide Leather (6), Thick Clefthoof Leather (4)"}
